#!/bin/sh
# Runs inside a throwaway builder container. Deploys a built celld project to Cloudflare with wrangler.
# In:  /tmp/in/project.tgz (the project FleetIQ deployed to celld, node_modules included)
#      /tmp/in/wrangler.cloudflare.json (generated by FleetIQ), optional /tmp/in/ca.pem
# Env: CLOUDFLARE_API_TOKEN, CLOUDFLARE_ACCOUNT_ID, D1_MIGRATE ("db1 db2"), DRY_RUN (1 = validate and bundle only)
set -eu
[ -s /tmp/in/ca.pem ] && export NODE_EXTRA_CA_CERTS=/tmp/in/ca.pem
export CI=1 WRANGLER_SEND_METRICS=false
WRANGLER="${WRANGLER_PKG:-wrangler@4}"
mkdir -p /tmp/p /tmp/out && tar xzf /tmp/in/project.tgz -C /tmp/p --no-same-owner
cp /tmp/in/wrangler.cloudflare.json /tmp/p/wrangler.cloudflare.json
cd /tmp/p
echo "==> $(bunx --bun "$WRANGLER" --version 2>/dev/null | tail -1)"
if [ "${DRY_RUN:-0}" = 1 ]; then
  echo "==> Dry run: validating the config and bundling (nothing is uploaded)"
  bunx --bun "$WRANGLER" deploy -c wrangler.cloudflare.json --dry-run --outdir /tmp/out/dist
  exit 0
fi
echo "==> Deploying to Cloudflare"
bunx --bun "$WRANGLER" deploy -c wrangler.cloudflare.json
for db in ${D1_MIGRATE:-}; do
  echo "==> D1 migrations for $db"
  bunx --bun "$WRANGLER" d1 migrations apply "$db" --remote -c wrangler.cloudflare.json
done
